REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO v_learning_tracking_runtime;
DO $$ BEGIN EXECUTE format('REVOKE CONNECT,CREATE,TEMPORARY ON DATABASE %I FROM PUBLIC',current_database()); END $$;
DO $$ BEGIN EXECUTE format('GRANT CONNECT ON DATABASE %I TO v_learning_tracking_runtime,v_learning_tracking_migration',current_database()); END $$;
GRANT SELECT,INSERT ON "training_program","training_program_version","program_rule_source","training_topic","assessment_definition","assessment_definition_version","assessment_topic","admission_requirement","student_training","lesson_source_snapshot","lesson_source_state","practical_training_record","practical_record_version","practical_record_topic","practical_record_response","theory_training_record","theory_record_version","theory_attendance","assessment_readiness","readiness_evaluation","readiness_requirement_result","readiness_evidence_basis","readiness_decision","assessment","assessment_result_version","assessment_topic_result","training_evidence_snapshot","training_evidence_item","training_evidence_check","reporting_declaration","learning_audit_event" TO v_learning_tracking_runtime;
GRANT UPDATE("category_code","name","revision") ON "training_program" TO v_learning_tracking_runtime;
GRANT UPDATE("program_id","version","status","pathway_code","required_theory_minutes","required_practical_minutes","theory_minutes_per_unit","practical_minutes_per_unit","effective_from","effective_to","legal_basis_verified","created_by","published_by","published_at","retired_at","journal_checklist_version_id") ON "training_program_version" TO v_learning_tracking_runtime;
GRANT UPDATE("program_version_id","rule_code","source_uri","source_edition","applicability","verified_by","verified_at","effective_from","effective_to","unit_description") ON "program_rule_source" TO v_learning_tracking_runtime;
GRANT UPDATE("program_version_id","topic_key","name","description") ON "training_topic" TO v_learning_tracking_runtime;
GRANT UPDATE("program_id","code") ON "assessment_definition" TO v_learning_tracking_runtime;
GRANT UPDATE("definition_id","program_id","program_version_id","name","training_kind","stage","minimum_mark","maximum_mark","passing_mark","required_for_completion") ON "assessment_definition_version" TO v_learning_tracking_runtime;
GRANT UPDATE("definition_version_id","program_version_id","topic_id") ON "assessment_topic" TO v_learning_tracking_runtime;
GRANT UPDATE("definition_version_id","program_version_id","code","kind","minimum_minutes","prerequisite_definition_version_id","minimum_mark") ON "admission_requirement" TO v_learning_tracking_runtime;
GRANT UPDATE("student_id","category_code","program_version_id","program_assigned_by","program_assigned_at","dependency_revision") ON "student_training" TO v_learning_tracking_runtime;
GRANT UPDATE("lesson_id","current_snapshot_id","freshness","last_verified_at","reason") ON "lesson_source_state" TO v_learning_tracking_runtime;
GRANT UPDATE("lesson_id","enrollment_id","current_version_id","revision") ON "practical_training_record" TO v_learning_tracking_runtime;
GRANT UPDATE("lesson_id","current_version_id","revision") ON "theory_training_record" TO v_learning_tracking_runtime;
GRANT UPDATE("enrollment_id","program_version_id","definition_version_id","current_evaluation_id","current_decision_id","revision") ON "assessment_readiness" TO v_learning_tracking_runtime;
GRANT UPDATE("enrollment_id","program_version_id","definition_version_id","attempt_number","appointment_id","revision") ON "assessment" TO v_learning_tracking_runtime;
GRANT UPDATE(invalidated_at,invalidated_by,invalidation_reason,invalidation_dependency_revision,invalidation_scope,invalidation_effective_at) ON readiness_decision TO v_learning_tracking_runtime;
 
CREATE FUNCTION lt_terminal_invalidation_guard() RETURNS trigger LANGUAGE plpgsql AS $guard$
BEGIN
 IF OLD.invalidated_at IS NOT NULL OR NEW.invalidated_at IS NULL OR
    (to_jsonb(OLD)-ARRAY['invalidated_at','invalidated_by','invalidation_reason','invalidation_dependency_revision','invalidation_scope','invalidation_effective_at']) IS DISTINCT FROM
    (to_jsonb(NEW)-ARRAY['invalidated_at','invalidated_by','invalidation_reason','invalidation_dependency_revision','invalidation_scope','invalidation_effective_at']) THEN
  RAISE EXCEPTION 'Readiness decision is immutable except one-time terminal invalidation';
 END IF;
 RETURN NEW;
END $guard$;
CREATE TRIGGER lt_terminal_invalidation BEFORE UPDATE ON readiness_decision FOR EACH ROW EXECUTE FUNCTION lt_terminal_invalidation_guard();
REVOKE ALL ON FUNCTION lt_terminal_invalidation_guard() FROM PUBLIC;
DO $secure$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND NOT EXISTS(SELECT 1 FROM pg_depend dep WHERE dep.classid='pg_proc'::regclass AND dep.objid=p.oid AND dep.deptype='e') LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,public,pg_temp',f.signature);
 END LOOP;
END $secure$;
